function twoSum(nums: number[], target: number): [number, number] {
  // Map from number value to its index seen so far
  const map = new Map<number, number>();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i]; // value we need
    if (map.has(complement)) {
      return [map.get(complement)!, i]; // non-null because we checked has
    }
    map.set(nums[i], i); // store after check to avoid using same index twice
  }
  throw new Error('No solution'); // per assumption should not happen
}
